function createVault(code) {
  let tries = 0;

  return {
    open(guess) {
      tries += 1;
      return guess === code;
    },
    getTries: () => tries,
  };
}

const vault = createVault("7391");

console.log(vault.open("0000"));
console.log(vault.open("7391"));
console.log(vault.getTries());
console.log(vault.code);
console.log(Object.keys(vault).join(","));
